+string TimestampCastErrorMessage(SRC input) {
+	if ((std::is_same<DST, dtime_t>() || std::is_same<DST, dtime_tz_t>()) && !input.IsFinite()) {
+		return "Can't get TIME of infinite TIMESTAMP";
